:root {
  --bg: #1a1c2c;
  --card: #2a2d3e;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #a0a0b0;
  --correct: #38b764;
  --wrong: #b13e53;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', monospace;
  font-size: 18px;
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
}

h1 {
  margin: 0 0 16px;
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.question {
  font-size: 28px;
  font-weight: bold;
  margin: 0 0 24px;
  min-height: 36px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 20px;
  cursor: pointer;
  border: 3px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  padding: 12px 24px;
  min-width: 80px;
  transition: transform 0.1s, background 0.1s;
}

button:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

button.correct {
  background: var(--correct);
  border-color: var(--correct);
  color: var(--text);
}

button.wrong {
  background: var(--wrong);
  border-color: var(--wrong);
  color: var(--text);
}

.score-line {
  font-size: 20px;
  margin: 0 0 24px;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.control {
  font-size: 18px;
  padding: 10px 20px;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  .answers {
    flex-direction: column;
    align-items: stretch;
  }
  .controls {
    flex-direction: column;
    align-items: stretch;
  }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let currentIndex = 0;
let score = 0;
let locked = false;

function render() {
  const q = questions[currentIndex];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  locked = false;
}

function updateScore() {
  scoreEl.textContent = String(score);
}

function handleAnswer(choice) {
  if (locked) return;
  locked = true;
  answerA.disabled = true;
  answerB.disabled = true;
  const q = questions[currentIndex];
  const chosenBtn = choice === 'a' ? answerA : answerB;
  const otherBtn = choice === 'a' ? answerB : answerA;
  if (choice === q.correct) {
    score += 1;
    chosenBtn.classList.add('correct');
  } else {
    chosenBtn.classList.add('wrong');
    otherBtn.classList.add('correct');
  }
  updateScore();
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (currentIndex < questions.length - 1) {
    currentIndex += 1;
    render();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  currentIndex = 0;
  score = 0;
  updateScore();
  render();
});

render();
updateScore();
